protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || tour.isEmpty()) {
        throw new IllegalArgumentException("Tour set cannot be null or empty");
    }

    // Create a map to store the adjacency list for quick lookup
    Map<V, List<E>> adjacencyList = new HashMap<>();
    for (E edge : tour) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        adjacencyList.computeIfAbsent(source, k -> new ArrayList<>()).add(edge);
        adjacencyList.computeIfAbsent(target, k -> new ArrayList<>()).add(edge);
    }

    // Find a starting vertex (any vertex with an edge in the tour)
    V startVertex = null;
    for (V vertex : adjacencyList.keySet()) {
        startVertex = vertex;
        break;
    }

    if (startVertex == null) {
        throw new IllegalStateException("No valid start vertex found in the tour");
    }

    // Reconstruct the path
    List<E> pathEdges = new ArrayList<>();
    Set<E> visitedEdges = new HashSet<>();
    V currentVertex = startVertex;

    while (visitedEdges.size() < tour.size()) {
        List<E> edges = adjacencyList.get(currentVertex);
        if (edges == null || edges.isEmpty()) {
            throw new IllegalStateException("Graph path is not continuous");
        }

        E nextEdge = null;
        for (E edge : edges) {
            if (!visitedEdges.contains(edge)) {
                nextEdge = edge;
                break;
            }
        }

        if (nextEdge == null) {
            throw new IllegalStateException("Graph path is not continuous");
        }

        pathEdges.add(nextEdge);
        visitedEdges.add(nextEdge);

        // Move to the next vertex
        currentVertex = graph.getEdgeSource(nextEdge).equals(currentVertex) 
                        ? graph.getEdgeTarget(nextEdge) 
                        : graph.getEdgeSource(nextEdge);
    }

    // Create and return the graph path
    return new GraphPathImpl<>(graph, startVertex, currentVertex, pathEdges, 0.0);
}

