public static String applyRelativePath(String path, String relativePath) {
    // Normalize the input paths by removing trailing slashes
    if (path.endsWith("/")) {
        path = path.substring(0, path.length() - 1);
    }
    if (relativePath.startsWith("/")) {
        relativePath = relativePath.substring(1);
    }

    // Split the paths into components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Use a stack to handle the path components
    Stack<String> pathStack = new Stack<>();
    for (String component : pathComponents) {
        pathStack.push(component);
    }

    // Process the relative path components
    for (String component : relativePathComponents) {
        if (component.equals("..")) {
            if (!pathStack.isEmpty()) {
                pathStack.pop(); // Move up one directory
            }
        } else if (!component.equals(".")) {
            pathStack.push(component); // Add the component to the path
        }
    }

    // Build the resulting path
    StringBuilder resultPath = new StringBuilder();
    while (!pathStack.isEmpty()) {
        resultPath.insert(0, pathStack.pop());
        if (!pathStack.isEmpty()) {
            resultPath.insert(0, "/");
        }
    }

    return resultPath.toString();
}

